// Slated's platform-independent engine for Linux: a JavaScript port of SlatedCore (Swift).
//
// Pure ES module code: no `gi://` imports, no Node built-ins, no DOM. It must run unchanged in GJS
// (the GNOME Shell extension and its preferences), Node and JavaScriptCore (tests on macOS).
// Behavior is pinned to the Swift implementation by the golden vectors in /fixtures (generated by
// `swift run SlatedFixtures`, checked by linux/tests: `make linux-test`).
//
// Data shapes are plain objects matching Slated's config.json (see docs/CONFIG.md):
//
// @typedef {{x: number, y: number, width: number, height: number}} Rect
//   Top-left-origin global coordinates (y grows down), like Mutter's frame rects.
// @typedef {{displayID: number, name: string, frame: Rect, visibleFrame: Rect, isMain: boolean, scale: number}} ScreenInfo
//   `visibleFrame` excludes panels/docks (Mutter's work area). Screens are given in OS order.
// @typedef {Object} Action
//   Canonical JSON form, identical to Swift's Action encoding: {op: "move", x, y, width, height, screen?},
//   {op: "push", direction, style?, screen?}, {op: "by-orientation", landscape: Action, portrait: Action}, …
//   Functions taking an Action also accept any form config.json allows (e.g. a Slate syntax string).
// @typedef {{key: string, modifiers: string[]}} KeyCombo
//   modifiers ⊆ ["ctrl", "alt", "shift", "cmd", "fn"], in that order; "cmd" is Super on Linux.
//   Config strings: "hyper+a".
// @typedef {{severity: "error"|"warning", message: string, file?: string, line?: number}} Diagnostic
// @typedef {{frame: Rect, screens: ScreenInfo[], settings?: Object<string, boolean|number|string>}} WindowContext
//
// Every function below is implemented in a sibling module and re-exported here; callers import only
// from this file. Errors are `SlatedError`s whose `message` matches the macOS app's text.

export {SlatedError} from './errors.js';

// --- Expressions (Slate's expression language) ---------------------------------------------------
/** (expression: string, variables: Object<string, number>) => number. Throws SlatedError("invalidExpression"). */
export {evaluateExpression, validateExpression, windowVariableNames, variableNames} from './expression.js';

// --- Slate syntax ---------------------------------------------------------------------------------
/**
 * parseOperation: "push left bar-resize:screenSizeX/2" → Action. Throws SlatedError.
 * formatOperation: Action → canonical Slate syntax (round-trips with parseOperation).
 * parseKeystroke: "a:ctrl,shift,alt,cmd" / "1:f4,ctrl,alt" → {keys: KeyCombo, modal: {keys: KeyCombo, toggle: boolean} | null}.
 * shellArguments: a `shell` command → [program, ...arguments], split the way Slate ran it (no shell).
 */
export {parseOperation, formatOperation, parseKeystroke, shellArguments} from './slateSyntax.js';
/**
 * parseSlateConfig(text, {path?, homeDirectory?, readFile?}) → {settings, bindings, layouts, defaults, diagnostics}.
 * `readFile(path)` returns the text of a sourced file, or null. describeDiagnostic(d) → ".slate, line 3: …".
 */
export {parseSlateConfig, describeDiagnostic} from './slateConfig.js';

// --- Window math ----------------------------------------------------------------------------------
/**
 * targetFrame(action, context: WindowContext) → Rect, for move/resize/push/nudge/throw/corner/by-orientation;
 *   throws SlatedError("screenNotFound") when the named screen doesn't exist (leave the window alone),
 *   and SlatedError("invalidSyntax") for other actions.
 * targetOrigin(action, context, actualSize: {width, height}) → {x, y}: where to put the window once it
 *   took `actualSize` (apps with minimum sizes).
 * resolveScreen(ref: string|number|null, context) → ScreenInfo | null (null ref = the window's screen).
 * screenContaining(screens, rect) and orderedLeftToRight(screens): Slate's screen helpers.
 */
export {targetFrame, targetOrigin, resolveScreen, screenContaining, orderedLeftToRight} from './frame.js';

// --- Configuration (config.json) ------------------------------------------------------------------
/**
 * decodeConfiguration(text) → configuration with every default filled in (JSON5 comments, trailing
 *   commas, unquoted keys allowed); throws SlatedError("invalidConfiguration") with `codingPath`. It reads
 *   both files' sections in one object (version 1's `settings` as `windows`); see configFiles.js for the files.
 * encodeConfiguration(config) → stable pretty JSON (sorted keys), byte for byte as Swift writes it.
 * starterConfiguration() → the author's Slate setup in native form (21 Hyper bindings), used on first
 *   run without a Slate config.
 * decodeAction(json) → canonical Action (throws like decodeConfiguration).
 * isWindowGeometry(action) → true for actions that move or resize the focused window (and can be undone).
 * isAutomation(action) → true for click, press, hold, repeat, wait and stop-automations (they synthesize input).
 * readSettings(settings) → Slate's global settings with typed values and Slate's defaults
 *   (defaultToCurrentScreen, repeatOnHoldOps, secondsBeforeRepeat, undoMaxStackSize, …).
 * randomUUID() → a new binding/hotstring id in Swift's uppercase form (ids must be UUIDs to decode).
 * clampKeyRepeat({delay, interval}) → keyboard.keyRepeat as config.json holds it: whole milliseconds
 *   clamped into KEY_REPEAT_RANGES ({delay: [100, 2000], interval: [15, 500]}), like Swift's KeyRepeat.
 */
export {
  decodeConfiguration,
  encodeConfiguration,
  starterConfiguration,
  decodeAction,
  isWindowGeometry,
  isAutomation,
  readSettings,
  randomUUID,
  clampKeyRepeat,
  KEY_REPEAT_RANGES,
} from './config.js';

// --- The two files (config.json and settings.json) -------------------------------------------------
/**
 * decodeConfigurationFiles(configText|null, settingsText|null) → {configuration, extras, legacy,
 *   configObject, settingsObject}: both files as one configuration; settings.json wins over version 1's
 *   settings sections in config.json. Errors name the file (`error.file`).
 * encodeConfigurationFiles(configuration, extras) → {config, settings}: the two files' texts.
 * isLegacyLayout(parsed config.json) → version 1's single file, to migrate; legacyConfig(parsed) → what it
 *   said about Slate files (Swift's LegacyConfig, the `legacy` decodeConfigurationFiles returns); legacySlateOptions(parsed)
 *   → {load, paths, imported}, version 1's Slate loading options. parseConfigText(text, file) → object.
 * CONFIG_SECTIONS, SETTINGS_SECTIONS: which sections each file holds; CONFIG_FILE, SETTINGS_FILE, BACKUP_FILE.
 */
export {
  decodeConfigurationFiles,
  encodeConfigurationFiles,
  isLegacyLayout,
  legacySlateOptions,
  legacyConfig,
  LEGACY_SETTINGS_SECTIONS,
  parseConfigText,
  CONFIG_SECTIONS,
  SETTINGS_SECTIONS,
  CONFIG_FILE,
  SETTINGS_FILE,
  BACKUP_FILE,
} from './configFiles.js';

// --- Keys -----------------------------------------------------------------------------------------
/**
 * parseKeyCombo("hyper+a") → KeyCombo (hyper = ctrl+alt+shift+cmd), or null if invalid.
 * formatKeyCombo(KeyCombo) → "hyper+a" (canonical config string).
 * displayKeyCombo(KeyCombo, {hyperGlyph = true}) → "✦A" / "⌃⌥⇧⌘A".
 * toGnomeAccelerator(KeyCombo | "hyper+a", {hyperMode: "modifiers"|"xkb"}) → "<Control><Alt><Shift><Super>a",
 *   or "<Hyper>a" with hyperMode "xkb"; null when the key has no keysym (mouse buttons). `fn` is ignored.
 * isModifierKey("shift") / isMouseButton("mouse4"): keys that can be held (automation) or bound only on
 *   macOS; neither is a GNOME shortcut on its own. keysymName("shift") → "Shift_L", the keysym to press.
 */
export {
  parseKeyCombo,
  formatKeyCombo,
  displayKeyCombo,
  toGnomeAccelerator,
  isModifierKey,
  isMouseButton,
  keysymName,
  keyDisplayName,
  MODIFIER_KEYS,
  MOUSE_BUTTON_KEYS,
} from './keys.js';

// --- Game automation ------------------------------------------------------------------------------
/**
 * parseSyntheticInput("key:shift+w") → {kind: "key", combo: KeyCombo} | {kind: "mouse", button} | null:
 *   what `press` and `hold` act on. formatSyntheticInput(input) → canonical text ("key:shift+w").
 * new RepeatSchedule({interval, times, jitter}): shouldRunAgain(runs) and nextInterval(random) for `repeat`.
 * MOUSE_BUTTONS, REPEAT_MODES, PRESS_PHASES: the values `click`, `repeat` and `press` take.
 */
export {parseSyntheticInput, formatSyntheticInput, RepeatSchedule, MOUSE_BUTTONS, REPEAT_MODES, PRESS_PHASES} from './automation.js';

// --- Clipboard history ----------------------------------------------------------------------------
/**
 * new ClipboardHistory(items, {newId}): add(text, {app, at, limit}), addImage(image, {app, at, limit}),
 *   addFiles(paths, {app, at, limit}), enforce(limit), prune(days, now), remove(id), togglePin(id), clear({keepPinned}),
 *   search(query), imageFiles, toJSON(); ClipboardHistory.fromJSON(parsed clipboard.json).
 *   Dates are Swift's (seconds since 2001-01-01): referenceSeconds(ms = Date.now()) converts.
 * foldedContains(text, word) → the case- and diacritic-insensitive match search uses.
 * fileDisplayName(path) → a copied file's name (its last path component), as a files item's text lists it.
 */
export {ClipboardHistory, referenceSeconds, referenceToMilliseconds, foldedContains, fileDisplayName} from './clipboard.js';

// --- Popup placement ------------------------------------------------------------------------------
/**
 * PopupPlacement.below(anchor, size, visibleFrame, gap = 4) → Rect: the clipboard picker under the caret
 *   (above it near the bottom of the screen). PopupPlacement.beside(target, row, size, visibleFrame, gap = 6)
 *   → Rect: the image preview beside the picker. Also clamp(rect, bounds), screen(anchor, screens) →
 *   ScreenInfo | null, and isUsable(rect, screenFrames, {maxHeight}) for a caret an app reported.
 */
export {PopupPlacement} from './placement.js';

// --- Action names and the island's cheat sheet ------------------------------------------------------
/**
 * actionTitle(action) → "Left Half", "Throw to Next Display", "Focus Safari": what the settings UI and the
 *   island call an action. actionSymbol(action) → its SF Symbol name (the GNOME island maps it to an icon).
 * actionRegion(action) → where a window action puts the window, as fractions of the screen, or null.
 * hyperCheatSheet(shortcuts, hyperModifiers) and modalCheatSheet(modal, shortcuts) → {title, isHyper,
 *   sections: [{title, items: [{id, label, title, region, symbol, keys, extraModifiers}]}]}: the shortcuts
 *   the island lists, grouped (CHEAT_SHEET_GROUPS) and in keyboard order; shortcuts are
 *   {keys, modal?, name?, action?, summary?} in registration order (the first for a key wins).
 */
export {actionTitle, actionSymbol, actionRegion, secondsTitle} from './actionNames.js';
export {hyperCheatSheet, modalCheatSheet, cheatSheetGroup, cheatSheetItems, CHEAT_SHEET_GROUPS} from './cheatSheet.js';

// --- Hotstrings -----------------------------------------------------------------------------------
/**
 * new HotstringMatcher(hotstrings).feed(text, appId) → {hotstring, deleteCount, delimiter} | null;
 *   also update(hotstrings), reset(), backspace().
 * expandTemplate("{date:yyyy-MM-dd}", {now?, clipboard?, locale?, timeZone?}) → expanded text.
 */
export {HotstringMatcher, expandTemplate} from './hotstrings.js';

// --- Config keys ------------------------------------------------------------------------------------
/**
 * Where each setting lives in the files, for the key the settings window shows under it:
 * CONFIG_KEYS.islandEnabled → {file: 'settings.json', components}; keyDisplay(key) →
 * "settings.json › island.enabled"; keyPath(key) → "island.enabled"; valueText(configuration, key) →
 * the value as the file has it. Items: hotstringKey(configuration, 1) → `config.json › hotstrings › ";sig"`.
 */
export {
  configKey,
  appendKey,
  itemKey,
  keyPath,
  keyDisplay,
  relativeDisplay,
  itemName,
  valueAt,
  valueText,
  SETTINGS as CONFIG_SETTINGS,
  CONFIG_KEYS,
  LISTS as CONFIG_LISTS,
  FIELDS as CONFIG_FIELDS,
  ACTION_PARAMETERS,
  NOT_SHOWN as CONFIG_NOT_SHOWN,
  bindingKey,
  hotstringKey,
  layoutKey,
  layoutAppKey,
} from './configKeys.js';
